"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["49913"],{7363(e){e.exports=JSON.parse('{"id":"FIN-1230","slug":"automatic-stabilizer","term":"Automatic Stabilizer","also_known_as":[],"difficulty":"Advanced","definition":"An automatic stabilizer is a feature of the tax and benefit system that automatically supports the economy during downturns and restrains it during booms, without any new decision by the government.","explanation":["Automatic stabilizers work because tax revenues and some types of spending change naturally with economic conditions.","During a recession, incomes and profits fall, so income and corporate tax revenues fall too, leaving more money with households and businesses. At the same time, more people qualify for unemployment and other benefits, so government spending rises. Both effects support demand. During a boom, the opposite happens: tax revenues rise and benefit spending falls, cooling demand.","For example, a worker who loses their job pays less income tax and starts receiving unemployment benefits, so their spending falls less than it would otherwise.","Automatic stabilizers act quickly, since they require no legislation, and they are larger in countries with progressive tax systems and generous benefits. They are one reason budget deficits widen during recessions. Economists distinguish them from discretionary fiscal policy, which involves deliberate decisions to change taxes or spending."],"note":"","total":1500,"prev":{"slug":"automated-clearing-house","term":"Automated Clearing House (ACH)"},"next":{"slug":"average-contract-value","term":"Average Contract Value (ACV)"}}')}}]);